def daily_aov(orders):
    acc = {}
    for o in orders:
        s, n = acc.get((o["store"], o["day"]), (0.0, 0))
        acc[(o["store"], o["day"])] = (s + o["total"], n + 1)
    return {k: s / n for k, (s, n) in acc.items()}


def monthly_aov(orders):
    daily = daily_aov(orders)
    acc = {}
    for (store, _day), aov in daily.items():
        s, n = acc.get(store, (0.0, 0))
        acc[store] = (s + aov, n + 1)
    return {k: round(s / n, 2) for k, (s, n) in acc.items()}


